<?php
/**
 * Dior Medical password-reset email template.
 *
 * Expected variables:
 * $patient_name       Recipient's display name.
 * $reset_password_url Secure reset URL generated by the existing password-reset flow.
 * $site_url           Optional website URL (defaults to the WordPress home URL).
 * $site_name          Optional site name.
 *
 * Include this template from the existing mailer after defining the variables.
 * This template does not generate or alter reset keys/URLs.
 */
if ( ! defined( 'ABSPATH' ) ) {
    exit;
}

$patient_name       = isset( $patient_name ) && $patient_name ? $patient_name : 'there';
$reset_password_url = isset( $reset_password_url ) ? $reset_password_url : '';
$site_url           = isset( $site_url ) && $site_url ? $site_url : home_url( '/' );
$site_name          = isset( $site_name ) && $site_name ? $site_name : 'DIOR MEDICAL';

$custom_logo_id = get_theme_mod( 'custom_logo' );
$custom_logo    = $custom_logo_id ? wp_get_attachment_image_src( $custom_logo_id, 'full' ) : false;
$logo_url       = ( is_array( $custom_logo ) && ! empty( $custom_logo[0] ) ) ? $custom_logo[0] : '';
?>
<!doctype html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <meta name="color-scheme" content="light">
    <title><?php echo esc_html( $site_name ); ?> - Reset Password</title>
</head>
<body style="margin:0;padding:0;background-color:#f2f7fc;font-family:Arial,Helvetica,sans-serif;color:#102b5c;">
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="width:100%;background-color:#f2f7fc;border-collapse:collapse;">
        <tr>
            <td align="center" style="padding:35px 12px;">
                <table role="presentation" width="600" cellpadding="0" cellspacing="0" border="0" style="width:100%;max-width:600px;background-color:#ffffff;border:1px solid #dce8f5;border-collapse:collapse;">

                    <!-- Branded header -->
                    <tr>
                        <td style="padding:25px 28px;background-color:#205b99;">
                            <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="border-collapse:collapse;">
                                <tr>
                                    <td width="42%" valign="middle" style="width:42%;padding-right:18px;">
                                        <?php if ( $logo_url ) : ?>
                                            <a href="<?php echo esc_url( $site_url ); ?>" style="display:inline-block;text-decoration:none;">
                                                <img src="<?php echo esc_url( $logo_url ); ?>" alt="<?php echo esc_attr( $site_name ); ?>" width="210" style="display:block;width:100%;max-width:210px;height:auto;border:0;outline:none;text-decoration:none;">
                                            </a>
                                        <?php else : ?>
                                            <a href="<?php echo esc_url( $site_url ); ?>" style="font-size:22px;line-height:28px;font-weight:700;color:#ffffff;text-decoration:none;"><?php echo esc_html( $site_name ); ?></a>
                                        <?php endif; ?>
                                    </td>
                                    <td width="58%" valign="middle" style="width:58%;padding-left:20px;border-left:1px solid #7ca4d0;color:#ffffff;font-size:15px;line-height:1.6;">
                                        Concierge Telehealth &amp;<br>Clinical Medicine
                                    </td>
                                </tr>
                            </table>
                        </td>
                    </tr>

                    <!-- Main message -->
                    <tr>
                        <td style="padding:34px 32px 32px;">
                            <h1 style="margin:0 0 25px;font-size:30px;line-height:1.25;font-weight:700;color:#102b60;">Reset Your Dior Medical Patient Portal Password</h1>
                            <p style="margin:0 0 25px;font-size:17px;line-height:1.7;color:#263c60;">Dear <?php echo esc_html( $patient_name ); ?>,</p>
                            <p style="margin:0 0 24px;font-size:17px;line-height:1.7;color:#263c60;">We received a request to reset your password for your <strong style="color:#0875ce;">DIOR MEDICAL</strong> patient portal account.</p>
                            <p style="margin:0 0 32px;font-size:17px;line-height:1.7;color:#263c60;">Click the button below to create a new password and regain access to your account.</p>

                            <!-- Bulletproof email button -->
                            <table role="presentation" align="center" cellpadding="0" cellspacing="0" border="0" style="margin:0 auto 25px;border-collapse:separate;">
                                <tr>
                                    <td align="center" bgcolor="#1769b0" style="background-color:#1769b0;border-radius:7px;">
                                        <?php if ( $reset_password_url ) : ?>
                                            <a href="<?php echo esc_url( $reset_password_url ); ?>" style="display:inline-block;padding:18px 35px;color:#ffffff;font-size:19px;line-height:24px;font-weight:bold;text-decoration:none;border-radius:7px;">Reset Password &nbsp;&rarr;</a>
                                        <?php else : ?>
                                            <span style="display:inline-block;padding:18px 35px;color:#ffffff;font-size:19px;line-height:24px;font-weight:bold;">Reset Password</span>
                                        <?php endif; ?>
                                    </td>
                                </tr>
                            </table>

                            <p style="margin:0 0 32px;text-align:center;color:#4776bd;font-size:15px;line-height:1.7;">This link will expire in 24 hours for your security.</p>

                            <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="width:100%;border-collapse:collapse;">
                                <tr><td style="border-top:1px solid #cbdcf0;font-size:0;line-height:0;">&nbsp;</td></tr>
                            </table>

                            <p style="margin:22px 0 0;font-size:14px;line-height:1.8;color:#657b99;">If you did not request a password reset, you can safely ignore this email. Your password will remain unchanged.</p>
                        </td>
                    </tr>

                    <!-- Footer -->
                    <tr>
                        <td style="padding:22px 20px;background-color:#f8fafc;border-top:1px solid #dce8f5;text-align:center;">
                            <p style="margin:0;font-size:14px;line-height:1.8;color:#647da4;">
                                &copy; <?php echo esc_html( gmdate( 'Y' ) ); ?> <?php echo esc_html( $site_name ); ?>. All rights reserved.
                                &nbsp;&bull;&nbsp;
                                <a href="<?php echo esc_url( $site_url ); ?>" style="color:#075bb5;text-decoration:underline;">Visit Website</a>
                            </p>
                        </td>
                    </tr>

                </table>
            </td>
        </tr>
    </table>
</body>
</html>
